// Added by #117: the sync System, the way out of no-async-value-as-state.
export interface ISyncOptions {
  timeout: number;
}
export interface ISyncResponse {
  data: string;
  time: number;
}
export type SyncCallback = (res: ISyncResponse, req: SyncRequest) => void;
export declare class SyncRequest {
  readonly from: MapPlayer;
  constructor(from: MapPlayer, data?: string, options?: ISyncOptions);
  start(data: string): boolean;
  then(callback: SyncCallback): this;
  catch(callback: SyncCallback): this;
}

// Added by #367 (no-event-response-outside-event): `on()` and its
// descriptor, whose handler runs in the event's context.
export interface EventDescriptor<P> {
  readonly name?: string;
  readonly register: (trigger: Trigger) => void;
  readonly read: () => P;
}
export interface Subscription {
  readonly trigger: Trigger;
  destroy(): void;
}
export declare function on<P>(
  event: EventDescriptor<P>,
  handler: (payload: P) => void,
  when?: (payload: P) => boolean,
): Subscription;
